 completed=[q for q in native if q['pass_']];development=next(q for q in native if not q['validation']);add(f"3. **Rzeczywiste S3 szybciej niż #158?** Nowe światy {len(native)}, ukończenia {len(completed)}, DNF {sum(not q['pass_'] for q in native)}. "+('Rozwojowe S3: '+n(development['finish_s'])+' s, baza '+n(development['pair']['baseline_finish_s'])+' s.\n' if completed else 'Brak nowego ukończenia S3; PARTIAL.\n'))
